import * as React from "react"
import { Textarea } from "@/components/ui/textarea"
import { cn } from "@/lib/utils"

type PromptInputContextValue = {
  value: string
  onValueChange: (value: string) => void
  onSubmit?: () => void
  disabled: boolean
  maxHeight: number | string
  textareaRef: React.RefObject<HTMLTextAreaElement | null>
}

const PromptInputContext = React.createContext<PromptInputContextValue | null>(null)

function usePromptInput() {
  const value = React.useContext(PromptInputContext)
  if (!value) throw new Error("PromptInputTextarea must be inside PromptInput")
  return value
}

export type PromptInputProps = {
  value: string
  onValueChange: (value: string) => void
  onSubmit?: () => void
  maxHeight?: number | string
  disabled?: boolean
  children: React.ReactNode
  className?: string
} & Omit<React.ComponentProps<"div">, "onSubmit">

function PromptInput({ value, onValueChange, onSubmit, maxHeight = 240, disabled = false,
  children, className, onClick, ...props }: PromptInputProps) {
  const textareaRef = React.useRef<HTMLTextAreaElement>(null)
  return (
    <PromptInputContext.Provider value={{ value, onValueChange, onSubmit, maxHeight, disabled, textareaRef }}>
      <div
        data-slot="prompt-input"
        className={cn("prompt-input", disabled && "cursor-not-allowed opacity-60", className)}
        onClick={event => {
          if (!disabled) textareaRef.current?.focus()
          onClick?.(event)
        }}
        {...props}
      >
        {children}
      </div>
    </PromptInputContext.Provider>
  )
}

export type PromptInputTextareaProps = { disableAutosize?: boolean } & React.ComponentProps<typeof Textarea>

function PromptInputTextarea({ className, disableAutosize = false, onKeyDown, ...props }: PromptInputTextareaProps) {
  const { value, onValueChange, onSubmit, disabled, maxHeight, textareaRef } = usePromptInput()
  const adjustHeight = React.useCallback((element: HTMLTextAreaElement | null) => {
    if (!element || disableAutosize) return
    element.style.height = "auto"
    element.style.height = typeof maxHeight === "number"
      ? `${Math.min(element.scrollHeight, maxHeight)}px`
      : `min(${element.scrollHeight}px, ${maxHeight})`
  }, [disableAutosize, maxHeight])
  React.useLayoutEffect(() => adjustHeight(textareaRef.current), [adjustHeight, textareaRef, value])
  return (
    <Textarea
      data-slot="prompt-input-textarea"
      ref={element => { textareaRef.current = element; adjustHeight(element) }}
      value={value}
      onChange={event => { adjustHeight(event.target); onValueChange(event.target.value) }}
      onKeyDown={event => {
        if (event.key =[REDACTED_CREDENTIAL] "Enter" && !event.shiftKey) { event.preventDefault(); onSubmit?.() }
        onKeyDown?.(event)
      }}
      disabled={disabled}
      className={cn("prompt-textarea", className)}
      {...props}
    />
  )
}

function PromptInputActions({ className, ...props }: React.ComponentProps<"div">) {
  return <div data-slot="prompt-input-actions" className={cn("flex items-center gap-2", className)} {...props} />
}

export { PromptInput, PromptInputTextarea, PromptInputActions }
